{
  "verdict": "request_changes",
  "summary": "Candidate implementation incorrectly rounds negative amounts that are exactly half, violating the spec that requires exact halves to round away from zero.",
  "findings": [
    {
      "finding_id": "defect-rounding-negative",
      "file": "candidate.py",
      "line_start": 1,
      "line_end": 2,
      "severity": "high",
      "description": "The function rounds negative amounts with a remainder of 50 (i.e., exact halves) towards zero instead of away from zero, breaking the symmetry requirement percent_of(-x, p) == -percent_of(x, p).",
      "evidence": "For amount_cents = -3 and percent = 50, the correct result should be -2, but the current implementation returns -1."
    }
  ]
}
